CREATE DATABASE IF NOT EXISTS obn_workflow CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
USE obn_workflow;

CREATE TABLE departments (id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY, name VARCHAR(100) NOT NULL UNIQUE, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE job_positions (id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY, name VARCHAR(100) NOT NULL UNIQUE);
CREATE TABLE employees (id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY, employee_code VARCHAR(30) NOT NULL UNIQUE, full_name VARCHAR(150) NOT NULL, email VARCHAR(150) UNIQUE, phone VARCHAR(40), department_id INT UNSIGNED, position_id INT UNSIGNED, position VARCHAR(100) NULL, avatar_path VARCHAR(255) NULL, bio VARCHAR(200) NULL, preferred_language ENUM('en','om','am') NOT NULL DEFAULT 'en', theme_preference ENUM('light','dark') NOT NULL DEFAULT 'light', profile_completed_at DATETIME NULL, active TINYINT(1) NOT NULL DEFAULT 1, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP, FOREIGN KEY (department_id) REFERENCES departments(id) ON DELETE SET NULL, FOREIGN KEY (position_id) REFERENCES job_positions(id) ON DELETE SET NULL, INDEX idx_employee_active (active));
CREATE TABLE users (id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY, employee_id INT UNSIGNED UNIQUE, username VARCHAR(80) NOT NULL UNIQUE, password_hash VARCHAR(255) NOT NULL, role VARCHAR(40) NOT NULL DEFAULT 'JOURNALIST', last_login_at DATETIME NULL, failed_attempts TINYINT UNSIGNED NOT NULL DEFAULT 0, locked_until DATETIME NULL, active TINYINT(1) NOT NULL DEFAULT 1, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, FOREIGN KEY (employee_id) REFERENCES employees(id) ON DELETE SET NULL);
CREATE TABLE program_types (id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY, name VARCHAR(100) NOT NULL UNIQUE, active TINYINT(1) NOT NULL DEFAULT 1);
CREATE TABLE rooms (id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY, code VARCHAR(30) NOT NULL UNIQUE, name VARCHAR(100) NOT NULL, room_type VARCHAR(80) NOT NULL, department_id INT UNSIGNED, status ENUM('AVAILABLE','OCCUPIED','IN_USE','MAINTENANCE','OFFLINE') DEFAULT 'AVAILABLE', equipment TEXT NULL, FOREIGN KEY (department_id) REFERENCES departments(id) ON DELETE SET NULL);
CREATE TABLE workflow_stages (id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY, stage_key VARCHAR(40) NOT NULL UNIQUE, name VARCHAR(100) NOT NULL, icon VARCHAR(40) NULL, description VARCHAR(255) NULL, sequence_no SMALLINT UNSIGNED NOT NULL, expected_minutes INT UNSIGNED NOT NULL DEFAULT 60, active TINYINT(1) NOT NULL DEFAULT 1);
CREATE TABLE programs (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, program_code VARCHAR(30) NOT NULL UNIQUE, title VARCHAR(200) NOT NULL, description TEXT NULL, language VARCHAR(80) DEFAULT 'Afaan Oromo', source VARCHAR(150) NULL, department_id INT UNSIGNED, program_type_id INT UNSIGNED, journalist_id INT UNSIGNED, producer_id INT UNSIGNED, presenter VARCHAR(150) NULL, priority ENUM('LOW','NORMAL','HIGH','URGENT') DEFAULT 'NORMAL', planned_start DATETIME NOT NULL, planned_broadcast DATETIME NULL, expected_duration_minutes INT UNSIGNED DEFAULT 60, current_stage_id INT UNSIGNED NULL, previous_stage_id INT UNSIGNED NULL, current_room_id INT UNSIGNED NULL, previous_room_id INT UNSIGNED NULL, current_employee_id INT UNSIGNED NULL, previous_employee_id INT UNSIGNED NULL, current_status ENUM('DRAFT','SUBMITTED','JOURNALED','IN_PROGRESS','IN_INGEST','IN_EDITING','IN_GRAPHICS','IN_AUDIO','IN_QC','READY_FOR_PLAYOUT','IN_MASTER_CONTROL','IN_UPLINK','DELAYED','ON_AIR','COMPLETED','FAILED','CANCELLED') DEFAULT 'DRAFT', current_started_at DATETIME NULL, progress TINYINT UNSIGNED NOT NULL DEFAULT 0, completed_at DATETIME NULL, created_by INT UNSIGNED, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP, FOREIGN KEY (department_id) REFERENCES departments(id) ON DELETE SET NULL, FOREIGN KEY (program_type_id) REFERENCES program_types(id) ON DELETE SET NULL, FOREIGN KEY (journalist_id) REFERENCES employees(id) ON DELETE SET NULL, FOREIGN KEY (producer_id) REFERENCES employees(id) ON DELETE SET NULL, FOREIGN KEY (current_stage_id) REFERENCES workflow_stages(id) ON DELETE SET NULL, FOREIGN KEY (previous_stage_id) REFERENCES workflow_stages(id) ON DELETE SET NULL, FOREIGN KEY (current_room_id) REFERENCES rooms(id) ON DELETE SET NULL, FOREIGN KEY (previous_room_id) REFERENCES rooms(id) ON DELETE SET NULL, FOREIGN KEY (current_employee_id) REFERENCES employees(id) ON DELETE SET NULL, FOREIGN KEY (previous_employee_id) REFERENCES employees(id) ON DELETE SET NULL, FOREIGN KEY (created_by) REFERENCES users(id) ON DELETE SET NULL, INDEX idx_program_status (current_status), INDEX idx_program_stage (current_stage_id), INDEX idx_program_broadcast (planned_broadcast));
CREATE TABLE program_stage_history (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, program_id BIGINT UNSIGNED NOT NULL, stage_id INT UNSIGNED NOT NULL, room_id INT UNSIGNED NULL, employee_id INT UNSIGNED NULL, status VARCHAR(40) NOT NULL DEFAULT 'IN_PROGRESS', planned_start DATETIME NULL, actual_start DATETIME NOT NULL, planned_end DATETIME NULL, actual_end DATETIME NULL, expected_minutes INT UNSIGNED NOT NULL DEFAULT 60, actual_minutes INT UNSIGNED NULL, delay_minutes INT NOT NULL DEFAULT 0, notes TEXT NULL, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, FOREIGN KEY (program_id) REFERENCES programs(id) ON DELETE CASCADE, FOREIGN KEY (stage_id) REFERENCES workflow_stages(id), FOREIGN KEY (room_id) REFERENCES rooms(id) ON DELETE SET NULL, FOREIGN KEY (employee_id) REFERENCES employees(id) ON DELETE SET NULL, INDEX idx_history_program (program_id));
CREATE TABLE program_journal (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, program_id BIGINT UNSIGNED NOT NULL UNIQUE, program_date DATE NOT NULL, scheduled_time TIME NULL, presenter VARCHAR(150) NULL, producer VARCHAR(150) NULL, source VARCHAR(150) NULL, initial_location VARCHAR(150) NULL, notes TEXT NULL, created_by INT UNSIGNED NULL, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP, FOREIGN KEY (program_id) REFERENCES programs(id) ON DELETE CASCADE, FOREIGN KEY (created_by) REFERENCES users(id) ON DELETE SET NULL, INDEX idx_journal_date (program_date));
CREATE TABLE program_movements (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, program_id BIGINT UNSIGNED NOT NULL, from_stage_id INT UNSIGNED NULL, from_room_id INT UNSIGNED NULL, to_stage_id INT UNSIGNED NOT NULL, to_room_id INT UNSIGNED NULL, moved_by INT UNSIGNED NULL, moved_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP, previous_duration_minutes INT UNSIGNED NOT NULL DEFAULT 0, notes TEXT NULL, FOREIGN KEY (program_id) REFERENCES programs(id) ON DELETE CASCADE, FOREIGN KEY (from_stage_id) REFERENCES workflow_stages(id) ON DELETE SET NULL, FOREIGN KEY (from_room_id) REFERENCES rooms(id) ON DELETE SET NULL, FOREIGN KEY (to_stage_id) REFERENCES workflow_stages(id), FOREIGN KEY (to_room_id) REFERENCES rooms(id) ON DELETE SET NULL, FOREIGN KEY (moved_by) REFERENCES users(id) ON DELETE SET NULL, INDEX idx_movements_program (program_id), INDEX idx_movements_date (moved_at));
CREATE TABLE delay_records (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, program_id BIGINT UNSIGNED NOT NULL, stage_id INT UNSIGNED NOT NULL, reason VARCHAR(100) NOT NULL, minutes INT UNSIGNED NOT NULL DEFAULT 0, notes TEXT NULL, recorded_by INT UNSIGNED NULL, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, FOREIGN KEY (program_id) REFERENCES programs(id) ON DELETE CASCADE, FOREIGN KEY (stage_id) REFERENCES workflow_stages(id), FOREIGN KEY (recorded_by) REFERENCES users(id) ON DELETE SET NULL);
CREATE TABLE program_performance (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, program_id BIGINT UNSIGNED NOT NULL UNIQUE, total_minutes INT UNSIGNED NOT NULL DEFAULT 0, total_delay_minutes INT UNSIGNED NOT NULL DEFAULT 0, completed_stages INT UNSIGNED NOT NULL DEFAULT 0, total_stages INT UNSIGNED NOT NULL DEFAULT 9, score DECIMAL(5,2) NOT NULL DEFAULT 0, performance_label VARCHAR(40) NOT NULL DEFAULT 'GOOD', calculated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP, FOREIGN KEY (program_id) REFERENCES programs(id) ON DELETE CASCADE);
CREATE TABLE issues (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, issue_code VARCHAR(30) NOT NULL UNIQUE, program_id BIGINT UNSIGNED NOT NULL, stage_id INT UNSIGNED NULL, room_id INT UNSIGNED NULL, reporter_id INT UNSIGNED NULL, issue_type VARCHAR(80) NOT NULL, priority ENUM('LOW','MEDIUM','HIGH','CRITICAL') DEFAULT 'MEDIUM', description TEXT NOT NULL, status ENUM('OPEN','ASSIGNED','IN_PROGRESS','RESOLVED','CLOSED') DEFAULT 'OPEN', assigned_technician_id INT UNSIGNED NULL, resolution TEXT NULL, resolved_at DATETIME NULL, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, FOREIGN KEY (program_id) REFERENCES programs(id) ON DELETE CASCADE, FOREIGN KEY (stage_id) REFERENCES workflow_stages(id) ON DELETE SET NULL, FOREIGN KEY (room_id) REFERENCES rooms(id) ON DELETE SET NULL, FOREIGN KEY (reporter_id) REFERENCES employees(id) ON DELETE SET NULL, FOREIGN KEY (assigned_technician_id) REFERENCES employees(id) ON DELETE SET NULL);
CREATE TABLE delays (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, program_id BIGINT UNSIGNED NOT NULL, stage_id INT UNSIGNED NOT NULL, employee_id INT UNSIGNED NULL, reason VARCHAR(100) NOT NULL, minutes INT UNSIGNED NOT NULL DEFAULT 0, corrective_action TEXT NULL, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, FOREIGN KEY (program_id) REFERENCES programs(id) ON DELETE CASCADE, FOREIGN KEY (stage_id) REFERENCES workflow_stages(id), FOREIGN KEY (employee_id) REFERENCES employees(id) ON DELETE SET NULL);
CREATE TABLE notifications (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, user_id INT UNSIGNED NULL, program_id BIGINT UNSIGNED NULL, type VARCHAR(60) NOT NULL, message VARCHAR(255) NOT NULL, read_at DATETIME NULL, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, FOREIGN KEY (user_id) REFERENCES users(id) ON DELETE CASCADE, FOREIGN KEY (program_id) REFERENCES programs(id) ON DELETE CASCADE);
CREATE TABLE password_reset_requests (id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY, user_id INT UNSIGNED NOT NULL, requested_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP, status ENUM('PENDING','ACTIONED','DISMISSED') NOT NULL DEFAULT 'PENDING', actioned_by INT UNSIGNED NULL, actioned_at DATETIME NULL, FOREIGN KEY (user_id) REFERENCES users(id) ON DELETE CASCADE, FOREIGN KEY (actioned_by) REFERENCES users(id) ON DELETE SET NULL, INDEX idx_password_reset_status (status, requested_at));
CREATE TABLE audit_logs (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, user_id INT UNSIGNED NULL, action VARCHAR(100) NOT NULL, entity_type VARCHAR(60) NOT NULL, entity_id VARCHAR(60) NULL, old_value JSON NULL, new_value JSON NULL, ip_address VARCHAR(45) NULL, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, FOREIGN KEY (user_id) REFERENCES users(id) ON DELETE SET NULL, INDEX idx_audit_created (created_at));
CREATE TABLE transmissions (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, program_id BIGINT UNSIGNED NOT NULL UNIQUE, operator_id INT UNSIGNED NULL, channel VARCHAR(100), scheduled_at DATETIME NULL, actual_start DATETIME NULL, actual_end DATETIME NULL, duration_minutes INT UNSIGNED NULL, signal_status VARCHAR(50), status ENUM('SCHEDULED','READY','ON_AIR','COMPLETED','INTERRUPTED','FAILED','DELAYED') DEFAULT 'SCHEDULED', incidents TEXT NULL, FOREIGN KEY (program_id) REFERENCES programs(id) ON DELETE CASCADE, FOREIGN KEY (operator_id) REFERENCES employees(id) ON DELETE SET NULL);
CREATE TABLE uplinks (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, program_id BIGINT UNSIGNED NOT NULL UNIQUE, station VARCHAR(100), operator_id INT UNSIGNED NULL, platform VARCHAR(100), signal_quality VARCHAR(50), started_at DATETIME NULL, ended_at DATETIME NULL, status ENUM('WAITING','READY','ACTIVE','COMPLETED','FAILED','INTERRUPTED') DEFAULT 'WAITING', technical_issue TEXT NULL, final_confirmation TINYINT(1) DEFAULT 0, FOREIGN KEY (program_id) REFERENCES programs(id) ON DELETE CASCADE, FOREIGN KEY (operator_id) REFERENCES employees(id) ON DELETE SET NULL);
ALTER TABLE programs MODIFY current_status ENUM('WAITING','IN_PROGRESS','BLOCKED','DELAYED','ON_AIR','COMPLETED','CANCELLED') NOT NULL DEFAULT 'WAITING';
